{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE `MapleMonk.STPL_pandl_intermediate` AS WITH daily_store_costs AS ( SELECT date_generated AS cost_date, UPPER(store) AS store, lower(type) AS cost_type, CASE WHEN lower(Commission_Type) LIKE \'%percent%\' THEN CAST(REPLACE(REPLACE(Actual_Value, \'%\', \'\'), \',\', \'\') AS FLOAT64) / 100 ELSE NULL END AS commission_percent, CASE WHEN lower(Commission_Type) NOT LIKE \'%percent%\' THEN CAST(REPLACE(REPLACE(Actual_Value, \'%\', \'\'), \',\', \'\') AS FLOAT64) / (DATE_DIFF(PARSE_DATE(\'%e-%b-%y\', END_DATE), PARSE_DATE(\'%e-%b-%y\', START_DATE), DAY) + 1) ELSE NULL END AS daily_fixed_value FROM MapleMonk.STPL_bnb_Offline_Cost, UNNEST(GENERATE_DATE_ARRAY( PARSE_DATE(\'%e-%b-%y\', START_DATE), PARSE_DATE(\'%e-%b-%y\', END_DATE) )) AS date_generated WHERE lower(type) != \'exhibition\' ), daily_exhibition_costs AS ( SELECT date_generated AS cost_date, UPPER(store) AS store, CASE WHEN lower(Commission_Type) LIKE \'%percent%\' THEN CAST(REPLACE(Actual_Value, \'%\', \'\') AS FLOAT64) / 100 ELSE NULL END AS commission_percent, CASE WHEN lower(Commission_Type) NOT LIKE \'%percent%\' THEN CAST(REPLACE(Actual_Value, \'%\', \'\') AS FLOAT64) / (DATE_DIFF(PARSE_DATE(\'%e-%b-%y\', END_DATE), PARSE_DATE(\'%e-%b-%y\', START_DATE), DAY) + 1) ELSE NULL END AS daily_fixed_value FROM `MapleMonk.STPL_bnb_Offline_Cost`, UNNEST(GENERATE_DATE_ARRAY( PARSE_DATE(\'%e-%b-%y\', START_DATE), PARSE_DATE(\'%e-%b-%y\', END_DATE) )) AS date_generated WHERE lower(type) = \'exhibition\' ), inventory_shares AS ( SELECT inv_date, store, brand, brand_inventory, SUM(brand_inventory) OVER (PARTITION BY inv_date, store) AS total_store_inventory, SAFE_DIVIDE(brand_inventory, SUM(brand_inventory) OVER (PARTITION BY inv_date, store)) AS inventory_share FROM ( SELECT DATA_FETCH_DATE AS inv_date, UPPER(TRIM(Channel)) AS store, UPPER(TRIM(BRAND)) AS brand, SUM(Available_Inventory) AS brand_inventory FROM `MapleMonk.ZOUK_STORE_INVENTORY_FACT_ITEMS` WHERE UPPER(TRIM(BRAND)) IN (\'EVERPRET\', \'ZOUK\', \'DOTO\') GROUP BY inv_date, store, brand ) ), ebo_stores AS ( SELECT DISTINCT UPPER(TRIM(store)) AS store FROM MapleMonk.STPL_bnb_Offline_Cost WHERE lower(type) != \'exhibition\' ), total_ebo_sales AS ( SELECT DATE(sc.ORDER_DATE) AS sales_date, UPPER(TRIM(sc.SOURCE)) AS store, SUM(IFNULL(sc.SELLING_PRICE, 0)) AS total_ebo_sales FROM MapleMonk.zouk_sales_consolidated_temp sc WHERE NOT (LOWER(IFNULL(sc.ORDER_STATUS, \'\')) LIKE \'%cancel%\' OR LOWER(IFNULL(sc.FINAL_SHIPPING_STATUS, \'\')) LIKE \'%cancel%\') AND UPPER(TRIM(sc.SOURCE)) IN (SELECT store FROM ebo_stores) GROUP BY sales_date, store ), cte AS ( SELECT COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date, store_rent.cost_date, store_cam.cost_date, store_elec.cost_date, store_int.cost_date, store_hvac.cost_date, store_other.cost_date, store_salary.cost_date, store_incentive.cost_date, store_bank.cost_date) AS Date_pre, CASE WHEN COALESCE(store_rent.store, store_cam.store, store_elec.store, store_int.store, store_hvac.store, store_other.store, store_salary.store, store_incentive.store, store_bank.store) IS NOT NULL THEN \'SHOPIFY POS\' ELSE sc.MARKETPLACE END AS MARKETPLACE_pre, COALESCE(FINAL_MARKETPLACE, CASE WHEN LOWER(COALESCE(msc.marketing_channel, mscc.marketing_nocategory_channel)) LIKE \'%amazon%\' THEN \'AMAZON\' WHEN LOWER(COALESCE(msc.marketing_channel, mscc.marketing_nocategory_channel)) LIKE ANY (\'facebook\',\'google\') THEN \'WEBSITE\' WHEN COALESCE(store_rent.store, store_cam.store, store_elec.store, store_int.store, store_hvac.store, store_other.store, store_salary.store, store_incentive.store, store_bank.store) IS NOT NULL THEN \'EBO\' ELSE LOWER(COALESCE(msc.marketing_channel, mscc.marketing_nocategory_channel)) END) AS FINAL_MARKETPLACE_pre, COALESCE(CHANNEL, msc.marketing_channel, mscc.marketing_nocategory_channel) AS channel_pre, UPPER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store, store_hvac.store, store_other.store, store_salary.store, store_incentive.store, store_bank.store)) AS SOURCE, REFERENCE_CODE, Order_id, CASE WHEN COALESCE(store_rent.store, store_cam.store, store_elec.store, store_int.store, store_hvac.store, store_other.store, store_salary.store, store_incentive.store, store_bank.store) IS NOT NULL THEN \'OFFLINE\' ELSE sc.Marketplace_Segment END AS marketplace_segment_pre, new_customer_flag, customer_id_final, CASE WHEN LOWER(COALESCE(sc.Brand, fsm.brand)) LIKE \'%everpret%\' THEN \'EVERPRET\' WHEN LOWER(COALESCE(sc.Brand, fsm.brand)) LIKE \'%doto%\' THEN \'DOTO\' ELSE LOWER(COALESCE(sc.Brand, fsm.brand)) END AS Brand_Pre, SKU, sc.COMMONSKU, UPPER(COALESCE(PRODUCT_CATEGORY, msc.category)) AS CATEGORY_PRE, PRODUCT_SUB_CATEGORY, sc.PRODUCT_TYPE, UPPER(COALESCE(sc.COLLECTION, msc.collection, mscc.collection)) AS collection_pre, sc.PRINT, COALESCE(sc.child_category_code, sc.category_code) AS category_code, SALEORDERITEMCODE, IFNULL(sc.BAU_MRP_ONLINE, 0) AS BAU_MRP_SALES, IFNULL(SELLING_PRICE, 0) AS SALES, IFNULL(CASE WHEN tm.marketplace IS NOT NULL THEN (CASE WHEN IFNULL(COALESCE(sc.BAU_MRP_ONLINE, SELLING_PRICE), 0) >= IFNULL(SELLING_PRICE, 0) THEN IFNULL(COALESCE(sc.BAU_MRP_ONLINE, SELLING_PRICE), 0) - IFNULL(SELLING_PRICE, 0) ELSE 0 END) ELSE 0 END, 0) AS bau_discount1, IFNULL(IFNULL(mc.commission_value, 0) * IFNULL(selling_price, 0), 0) AS muntr_sor, IFNULL(CASE WHEN tm.marketplace IS NOT NULL THEN (CASE WHEN IFNULL(COALESCE(sc.BAU_MRP_ONLINE, SELLING_PRICE), 0) >= IFNULL(SELLING_PRICE, 0) THEN IFNULL(COALESCE(sc.BAU_MRP_ONLINE, SELLING_PRICE), 0) - IFNULL(SELLING_PRICE, 0) ELSE 0 END) ELSE 0 END, 0) + IFNULL(IFNULL(ccogs.commission_value, 0) * IFNULL(COALESCE(sc.BAU_MRP_ONLINE, SELLING_PRICE), 0), 0) + IFNULL(SAFE_DIVIDE(IFNULL(ccogs.actual_value, 0), COUNT(*) OVER (PARTITION BY ccogs.start_date, ccogs.end_date, LOWER(ccogs.MARKETPLACE))), 0) AS TRADE_MARGIN, IFNULL(IFNULL(ccogs.commission_value, 0) * IFNULL(COALESCE(sc.BAU_MRP_ONLINE, SELLING_PRICE), 0), 0) + IFNULL(SAFE_DIVIDE(IFNULL(ccogs.actual_value, 0), COUNT(*) OVER (PARTITION BY ccogs.start_date, ccogs.end_date, LOWER(ccogs.MARKETPLACE))), 0) AS CCOGS, CASE WHEN tm.marketplace IS NULL THEN (CASE WHEN IFNULL(COALESCE(sc.BAU_MRP_ONLINE, SELLING_PRICE), 0) >= IFNULL(SELLING_PRICE, 0) THEN IFNULL(COALESCE(sc.BAU_MRP_ONLINE, SELLING_PRICE), 0) - IFNULL(SELLING_PRICE, 0) ELSE 0 END) ELSE 0 END AS BAU_DISCOUNT, (0.18 * (IFNULL(SELLING_PRICE, 0) - IFNULL(RS.commission_value * IFNULL(SELLING_PRICE, 0), 0))) / (1 + 0.18) AS GST, IFNULL(cm.commission_value * IFNULL(selling_price, 0), 0) AS CHANNEL_MARGIN, CASE WHEN IFNULL(RS.commission_value, 0) * IFNULL(selling_price, 0) = 0 THEN SAFE_DIVIDE(RS.Actual_value, COUNT(*) OVER (PARTITION BY LAST_DAY(COALESCE(order_date, rs.start_date)), LOWER(COALESCE(sc.marketplace, rs.marketplace)))) ELSE RS.commission_value * IFNULL(selling_price, 0) END AS RETURNS, CASE WHEN IFNULL(lc.commission_value, 0) * (CASE WHEN tm.marketplace IS NOT NULL THEN IFNULL(COALESCE(sc.BAU_MRP_ONLINE, SELLING_PRICE), 0) ELSE IFNULL(selling_price, 0) END) = 0 THEN SAFE_DIVIDE(lc.Actual_value, COUNT(*) OVER (PARTITION BY LAST_DAY(COALESCE(order_date, lc.start_date)), LOWER(COALESCE(sc.marketplace, lc.marketplace)))) ELSE lc.commission_value * (CASE WHEN tm.marketplace IS NOT NULL THEN IFNULL(COALESCE(sc.BAU_MRP_ONLINE, SELLING_PRICE), 0) ELSE IFNULL(selling_price, 0) END) END AS LOGISTICS_COST, IFNULL(SC.quantity, 0) AS Quantity, (cogs.cogs * IFNULL(quantity, 0)) - IFNULL(CASE WHEN cm.MARKETPLACE IS NOT NULL THEN rs.commission_value * (cogs.cogs * IFNULL(quantity, 0)) END, 0) AS cogs, (cogs.cogs * IFNULL(quantity, 0)) AS initial_cogs, IFNULL( store.daily_fixed_value * SAFE_DIVIDE(IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store.store)))), store.daily_fixed_value ) + IFNULL(store.commission_percent * IFNULL(selling_price, 0), 0) AS exhibition_cost, IFNULL( CASE WHEN inv_a.inventory_share IS NOT NULL THEN store_rent.daily_fixed_value * inv_a.inventory_share * SAFE_DIVIDE(IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store_rent.store)), LOWER(COALESCE(sc.Brand, fsm.brand)))) ELSE store_rent.daily_fixed_value * SAFE_DIVIDE(IFNULL(selling_price, 0), NULLIF(ebo.total_ebo_sales, 0)) END, store_rent.daily_fixed_value * COALESCE(inv_a.inventory_share, 1) ) + IFNULL(store_rent.commission_percent * IFNULL(selling_price, 0), 0) AS store_rent, IFNULL( CASE WHEN inv_a.inventory_share IS NOT NULL THEN store_cam.daily_fixed_value * inv_a.inventory_share * SAFE_DIVIDE(IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store)), LOWER(COALESCE(sc.Brand, fsm.brand)))) ELSE store_cam.daily_fixed_value * SAFE_DIVIDE(IFNULL(selling_price, 0), NULLIF(ebo.total_ebo_sales, 0)) END, store_cam.daily_fixed_value * COALESCE(inv_a.inventory_share, 1) ) + IFNULL(store_cam.commission_percent * IFNULL(selling_price, 0), 0) AS store_cam, IFNULL( CASE WHEN inv_a.inventory_share IS NOT NULL THEN store_elec.daily_fixed_value * inv_a.inventory_share * SAFE_DIVIDE(IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store)), LOWER(COALESCE(sc.Brand, fsm.brand)))) ELSE store_elec.daily_fixed_value * SAFE_DIVIDE(IFNULL(selling_price, 0), NULLIF(ebo.total_ebo_sales, 0)) END, store_elec.daily_fixed_value * COALESCE(inv_a.inventory_share, 1) ) + IFNULL(store_elec.commission_percent * IFNULL(selling_price, 0), 0) AS store_elec, IFNULL( CASE WHEN inv_a.inventory_share IS NOT NULL THEN store_int.daily_fixed_value * inv_a.inventory_share * SAFE_DIVIDE(IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store)), LOWER(COALESCE(sc.Brand, fsm.brand)))) ELSE store_int.daily_fixed_value * SAFE_DIVIDE(IFNULL(selling_price, 0), NULLIF(ebo.total_ebo_sales, 0)) END, store_int.daily_fixed_value * COALESCE(inv_a.inventory_share, 1) ) + IFNULL(store_int.commission_percent * IFNULL(selling_price, 0), 0) AS store_int, IFNULL( CASE WHEN inv_a.inventory_share IS NOT NULL THEN store_hvac.daily_fixed_value * inv_a.inventory_share * SAFE_DIVIDE(IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store, store_hvac.store)), LOWER(COALESCE(sc.Brand, fsm.brand)))) ELSE store_hvac.daily_fixed_value * SAFE_DIVIDE(IFNULL(selling_price, 0), NULLIF(ebo.total_ebo_sales, 0)) END, store_hvac.daily_fixed_value * COALESCE(inv_a.inventory_share, 1) ) + IFNULL(store_hvac.commission_percent * IFNULL(selling_price, 0), 0) AS store_hvac, IFNULL( CASE WHEN inv_a.inventory_share IS NOT NULL THEN store_other.daily_fixed_value * inv_a.inventory_share * SAFE_DIVIDE(IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store, store_hvac.store, store_other.store)), LOWER(COALESCE(sc.Brand, fsm.brand)))) ELSE store_other.daily_fixed_value * SAFE_DIVIDE(IFNULL(selling_price, 0), NULLIF(ebo.total_ebo_sales, 0)) END, store_other.daily_fixed_value * COALESCE(inv_a.inventory_share, 1) ) + IFNULL(store_other.commission_percent * IFNULL(selling_price, 0), 0) AS store_other, IFNULL( store_salary.daily_fixed_value * SAFE_DIVIDE(IFNULL(selling_price, 0), NULLIF(ebo.total_ebo_sales, 0)), store_salary.daily_fixed_value ) + IFNULL(store_salary.commission_percent * IFNULL(selling_price, 0), 0) AS store_salary, IFNULL( store_incentive.daily_fixed_value * SAFE_DIVIDE(IFNULL(selling_price, 0), NULLIF(ebo.total_ebo_sales, 0)), store_incentive.daily_fixed_value ) + IFNULL(store_incentive.commission_percent * IFNULL(selling_price, 0), 0) AS store_incentive, IFNULL( store_bank.daily_fixed_value * SAFE_DIVIDE(IFNULL(selling_price, 0), NULLIF(ebo.total_ebo_sales, 0)), store_bank.daily_fixed_value ) + IFNULL(store_bank.commission_percent * IFNULL(selling_price, 0), 0) AS store_bank, store_revenue.commission_percent AS store_revenue_Share FROM ( SELECT sc.*, COALESCE((IFNULL(SELLING_PRICE, 0)) / (1 - tm.commission_value), GREATEST(IFNULL(BAU_ONLINE, 0), IFNULL(SELLING_PRICE, 0))) AS BAU_MRP_ONLINE FROM MapleMonk.zouk_sales_consolidated_temp sc LEFT JOIN ( SELECT PARSE_DATE(\'%d-%b-%y\', START_DATE) START_DATE, PARSE_DATE(\'%d-%b-%y\', END_DATE) END_DATE, MARKETPLACE, CAST(REPLACE(IFNULL(commission_value, \'0\'), \'%\', \'\') AS FLOAT64) / 100 AS commission_value, CAST(Actual_Value AS FLOAT64) AS Actual_Value FROM MapleMonk.STPL_Marketplace_Commissions WHERE UPPER(PANDL_CATEGORY) = \'TRADE MARGIN\' QUALIFY ROW_NUMBER() OVER (PARTITION BY START_DATE, END_DATE, LOWER(marketplace) ORDER BY 1) = 1 ) tm ON CAST(ORDER_DATE AS DATE) >= CAST(tm.START_DATE AS DATE) AND CAST(ORDER_DATE AS DATE) <= CAST(tm.END_DATE AS DATE) AND LOWER(sc.marketplace) = LOWER(tm.MARKETPLACE) WHERE NOT (LOWER(IFNULL(ORDER_STATUS, \'\')) LIKE \'%cancel%\' OR LOWER(IFNULL(FINAL_SHIPPING_STATUS, \'\')) LIKE \'%cancel%\') AND LOWER(brand) LIKE ANY (\'%everpret%\', \'%doto%\') ) SC LEFT JOIN (SELECT DISTINCT UPPER(MARKETPLACE) AS MARKETPLACE FROM MapleMonk.STPL_Marketplace_Commissions WHERE UPPER(PANDL_CATEGORY) = \'TRADE MARGIN\') tm ON LOWER(sc.marketplace) = LOWER(tm.MARKETPLACE) LEFT JOIN ( SELECT PARSE_DATE(\'%d-%b-%y\', START_DATE) START_DATE, PARSE_DATE(\'%d-%b-%y\', END_DATE) END_DATE, MARKETPLACE, CASE WHEN LOWER(Commission_Type) LIKE \'%percent%\' THEN CAST(REPLACE(commission_value, \'%\', \'\') AS FLOAT64) / 100 END AS commission_value, CASE WHEN LOWER(Commission_Type) NOT LIKE \'%percent%\' AND CURRENT_DATE() > PARSE_DATE(\'%d-%b-%y\', END_DATE) THEN CAST(REPLACE(commission_value, \',\', \'\') AS FLOAT64) ELSE (CAST(REPLACE(commission_Value, \'%\', \'\') AS FLOAT64) / CAST(EXTRACT(DAY FROM PARSE_DATE(\'%d-%b-%y\', END_DATE)) AS INT64)) * CAST(EXTRACT(DAY FROM CURRENT_DATE()) AS INT64) END AS actual_value FROM MapleMonk.c_cogs WHERE UPPER(PANDL_CATEGORY) = \'C COGS\' ) ccogs ON CAST(ORDER_DATE AS DATE) >= CAST(ccogs.START_DATE AS DATE) AND CAST(ORDER_DATE AS DATE) <= CAST(ccogs.END_DATE AS DATE) AND LOWER(sc.marketplace) = LOWER(ccogs.MARKETPLACE) LEFT JOIN ( SELECT PARSE_DATE(\'%d-%b-%y\', START_DATE) START_DATE, PARSE_DATE(\'%d-%b-%y\', END_DATE) END_DATE, MARKETPLACE, CAST(REPLACE(IFNULL(commission_value, \'0\'), \'%\', \'\') AS FLOAT64) / 100 AS commission_value, CAST(Actual_Value AS FLOAT64) AS Actual_Value FROM MapleMonk.STPL_Marketplace_Commissions WHERE UPPER(PANDL_CATEGORY) = \'TRADE MARGIN\' AND LOWER(marketplace) LIKE \'%myntra_sor%\' ) mc ON CAST(ORDER_DATE AS DATE) >= CAST(mc.START_DATE AS DATE) AND CAST(ORDER_DATE AS DATE) <= CAST(mc.END_DATE AS DATE) AND LOWER(sc.marketplace) = LOWER(mc.MARKETPLACE) LEFT JOIN (SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY LOWER(IFNULL(commonsku, \'\')) ORDER BY 1) rw FROM maplemonk.final_sku_master) WHERE rw = 1) fsm ON LOWER(fsm.commonsku) = LOWER(IFNULL(sc.commonsku, \'\')) LEFT JOIN ( SELECT PARSE_DATE(\'%d-%b-%y\', START_DATE) START_DATE, PARSE_DATE(\'%d-%b-%y\', END_DATE) END_DATE, MARKETPLACE, PANDL_CATEGORY, CAST(REPLACE(commission_value, \'%\', \'\') AS FLOAT64) / 100 AS commission_value, CAST(Actual_Value AS FLOAT64) AS Actual_Value FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY START_DATE, END_DATE, LOWER(MARKETPLACE) ORDER BY 1) rw FROM MapleMonk.STPL_Marketplace_Commissions) WHERE UPPER(PANDL_CATEGORY) = \'CHANNEL MARGIN\' AND rw = 1 ) cm ON CAST(ORDER_DATE AS DATE) >= CAST(cm.START_DATE AS DATE) AND CAST(ORDER_DATE AS DATE) <= CAST(cm.END_DATE AS DATE) AND LOWER(sc.marketplace) = LOWER(cm.MARKETPLACE) LEFT JOIN ( SELECT PARSE_DATE(\'%d-%b-%y\', START_DATE) START_DATE, PARSE_DATE(\'%d-%b-%y\', END_DATE) END_DATE, MARKETPLACE, CAST(REPLACE(Estimated_Return_Share, \'%\', \'\') AS FLOAT64) / 100 AS commission_value, CAST(Actual_Return_Value AS FLOAT64) AS Actual_Value FROM MapleMonk.STPL_returns_share ) rs ON CAST(ORDER_DATE AS DATE) >= CAST(rs.START_DATE AS DATE) AND CAST(ORDER_DATE AS DATE) <= CAST(rs.END_DATE AS DATE) AND LOWER(sc.marketplace) = LOWER(rs.MARKETPLACE) LEFT JOIN ( SELECT PARSE_DATE(\'%d-%b-%y\', START_DATE) START_DATE, PARSE_DATE(\'%d-%b-%y\', END_DATE) END_DATE, category_code, CAST(REPLACE(cogs, \',\', \'\') AS FLOAT64) AS cogs FROM `MapleMonk.zouk_db_SKU_MRP_COGS` QUALIFY ROW_NUMBER() OVER (PARTITION BY START_DATE, END_DATE, LOWER(category_code) ORDER BY 1) = 1 ) cogs ON CAST(sc.ORDER_DATE AS DATE) >= CAST(cogs.START_DATE AS DATE) AND CAST(sc.ORDER_DATE AS DATE) <= CAST(cogs.END_DATE AS DATE) AND LOWER(COALESCE(sc.child_category_code, sc.category_code)) = LOWER(cogs.category_code) FULL OUTER JOIN ( SELECT CAST(NULL AS DATE) AS marketing_date, CAST(NULL AS STRING) AS marketing_channel, CAST(NULL AS STRING) AS category, CAST(NULL AS STRING) AS collection, 0 AS spend, 0 AS Brand_Spend FROM maplemonk.STPL_MARKETING_CONSOLIDATED_temp LIMIT 0 ) msc ON CAST(msc.marketing_date AS DATE) = CAST(sc.order_Date AS DATE) AND LOWER(msc.marketing_channel) = LOWER(sc.channel) AND LOWER(sc.PRODUCT_CATEGORY) = LOWER(msc.category) FULL OUTER JOIN ( SELECT CAST(NULL AS DATE) AS marketing_nocategory_date, CAST(NULL AS STRING) AS marketing_nocategory_channel, CAST(NULL AS STRING) AS collection, 0 AS spend, 0 AS Brand_Spend FROM maplemonk.STPL_MARKETING_CONSOLIDATED_temp LIMIT 0 ) mscc ON CAST(mscc.marketing_nocategory_date AS DATE) = COALESCE(CAST(sc.order_Date AS DATE), CAST(msc.marketing_date AS DATE)) AND LOWER(mscc.marketing_nocategory_channel) = COALESCE(LOWER(sc.channel), LOWER(msc.marketing_channel)) AND LOWER(sc.collection) = LOWER(mscc.collection) FULL OUTER JOIN (SELECT cost_date, store, commission_percent, daily_fixed_value FROM daily_exhibition_costs) store ON CAST(ORDER_DATE AS DATE) = store.cost_date AND LOWER(sc.source) = LOWER(store.store) FULL OUTER JOIN (SELECT cost_date, store, commission_percent, daily_fixed_value FROM daily_store_costs WHERE cost_type = \'rent\') store_rent ON CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE) = store_rent.cost_date AND LOWER(sc.source) = LOWER(store_rent.store) FULL OUTER JOIN (SELECT cost_date, store, commission_percent, daily_fixed_value FROM daily_store_costs WHERE cost_type LIKE \'%cam charges%\') store_cam ON CAST(COALESCE(ORDER_DATE, marketing_date, marketing_nocategory_date, store_rent.cost_date) AS DATE) = store_cam.cost_date AND LOWER(COALESCE(SOURCE, store_rent.store)) = LOWER(store_cam.store) FULL OUTER JOIN (SELECT cost_date, store, commission_percent, daily_fixed_value FROM daily_store_costs WHERE cost_type LIKE \'%electricity exp%\') store_elec ON CAST(COALESCE(ORDER_DATE, marketing_date, marketing_nocategory_date, store_rent.cost_date, store_cam.cost_date) AS DATE) = store_elec.cost_date AND LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store)) = LOWER(store_elec.store) FULL OUTER JOIN (SELECT cost_date, store, commission_percent, daily_fixed_value FROM daily_store_costs WHERE cost_type LIKE \'%internet exp%\') store_int ON CAST(COALESCE(ORDER_DATE, marketing_date, marketing_nocategory_date, store_rent.cost_date, store_cam.cost_date, store_elec.cost_date) AS DATE) = store_int.cost_date AND LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store)) = LOWER(store_int.store) FULL OUTER JOIN (SELECT cost_date, store, commission_percent, daily_fixed_value FROM daily_store_costs WHERE cost_type LIKE \'hvac%\') store_hvac ON CAST(COALESCE(ORDER_DATE, marketing_date, marketing_nocategory_date, store_rent.cost_date, store_cam.cost_date, store_elec.cost_date, store_int.cost_date) AS DATE) = store_hvac.cost_date AND LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store)) = LOWER(store_hvac.store) FULL OUTER JOIN (SELECT cost_date, store, commission_percent, daily_fixed_value FROM daily_store_costs WHERE cost_type LIKE \'other store expenses%\') store_other ON CAST(COALESCE(ORDER_DATE, marketing_date, marketing_nocategory_date, store_rent.cost_date, store_cam.cost_date, store_elec.cost_date, store_int.cost_date, store_hvac.cost_date) AS DATE) = store_other.cost_date AND LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store, store_hvac.store)) = LOWER(store_other.store) FULL OUTER JOIN (SELECT cost_date, store, commission_percent, daily_fixed_value FROM daily_store_costs WHERE cost_type LIKE \'staff salary%\') store_salary ON CAST(COALESCE(ORDER_DATE, marketing_date, marketing_nocategory_date, store_rent.cost_date, store_cam.cost_date, store_elec.cost_date, store_int.cost_date, store_hvac.cost_date, store_other.cost_date) AS DATE) = store_salary.cost_date AND LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store, store_hvac.store, store_other.store)) = LOWER(store_salary.store) FULL OUTER JOIN (SELECT cost_date, store, commission_percent, daily_fixed_value FROM daily_store_costs WHERE cost_type LIKE \'staff incentive%\') store_incentive ON CAST(COALESCE(ORDER_DATE, marketing_date, marketing_nocategory_date, store_rent.cost_date, store_cam.cost_date, store_elec.cost_date, store_int.cost_date, store_hvac.cost_date, store_other.cost_date, store_salary.cost_date) AS DATE) = store_incentive.cost_date AND LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store, store_hvac.store, store_other.store, store_salary.store)) = LOWER(store_incentive.store) FULL OUTER JOIN (SELECT cost_date, store, commission_percent, daily_fixed_value FROM daily_store_costs WHERE cost_type LIKE \'bank comm%\') store_bank ON CAST(COALESCE(ORDER_DATE, marketing_date, marketing_nocategory_date, store_rent.cost_date, store_cam.cost_date, store_elec.cost_date, store_int.cost_date, store_hvac.cost_date, store_other.cost_date, store_salary.cost_date, store_incentive.cost_date) AS DATE) = store_bank.cost_date AND LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store, store_hvac.store, store_other.store, store_salary.store, store_incentive.store)) = LOWER(store_bank.store) FULL OUTER JOIN ( SELECT PARSE_DATE(\'%d-%b-%y\', START_DATE) START_DATE, PARSE_DATE(\'%d-%b-%y\', END_DATE) END_DATE, store, CAST(REPLACE(Actual_Value, \'%\', \'\') AS FLOAT64) / 100 AS commission_percent FROM MapleMonk.zouk_db_OFFLINE_STORE_COSTS WHERE LOWER(type) LIKE \'revenue share%\' ) store_revenue ON CAST(ORDER_DATE AS DATE) >= CAST(store_revenue.START_DATE AS DATE) AND CAST(ORDER_DATE AS DATE) <= CAST(store_revenue.END_DATE AS DATE) AND LOWER(SOURCE) = LOWER(store_revenue.store) LEFT JOIN ( SELECT PARSE_DATE(\'%d-%b-%y\', START_DATE) START_DATE, PARSE_DATE(\'%d-%b-%y\', END_DATE) END_DATE, MARKETPLACE, CAST(REPLACE(Estimated_Logistics_Cost, \'%\', \'\') AS FLOAT64) / 100 AS commission_value, CAST(Actual_Value AS FLOAT64) AS Actual_Value FROM MapleMonk.STPL_LOGISTICS_COSTS QUALIFY ROW_NUMBER() OVER (PARTITION BY START_DATE, END_DATE, LOWER(MARKETPLACE) ORDER BY 1) = 1 ) lc ON CAST(ORDER_DATE AS DATE) >= CAST(lc.START_DATE AS DATE) AND CAST(ORDER_DATE AS DATE) <= CAST(lc.END_DATE AS DATE) AND LOWER(sc.marketplace) = LOWER(lc.MARKETPLACE) LEFT JOIN inventory_shares inv_a ON CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date, store_rent.cost_date, store_cam.cost_date, store_elec.cost_date, store_int.cost_date, store_hvac.cost_date, store_other.cost_date) AS DATE) = inv_a.inv_date AND UPPER(TRIM(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store, store_hvac.store, store_other.store))) = inv_a.store AND UPPER(TRIM(COALESCE(sc.Brand, fsm.brand))) = inv_a.brand LEFT JOIN total_ebo_sales ebo ON CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date, store_rent.cost_date, store_cam.cost_date, store_elec.cost_date, store_int.cost_date, store_hvac.cost_date, store_other.cost_date) AS DATE) = ebo.sales_date AND UPPER(TRIM(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store, store_hvac.store, store_other.store))) = ebo.store ) SELECT COALESCE(sc.date_pre, msc.marketing_date, mscc.marketing_date, msccc.marketing_date) AS Date, UPPER(COALESCE(sc.Marketplace_pre, msc.Marketplace, mscc.marketplace, msccc.marketplace)) AS MARKETPLACE, UPPER(COALESCE(sc.Channel_pre, msc.Channel, mscc.Channel, msccc.Channel)) AS Channel, UPPER(COALESCE(sc.collection_pre, msc.collection, mscc.collection)) AS COLLECTION, UPPER(COALESCE(sc.marketplace_segment_pre, msc.marketplace_segment, mscc.marketplace_segment, msccc.marketplace_segment)) AS marketplace_segment, UPPER(COALESCE(sc.category_pre, msc.Category)) AS PRODUCT_CATEGORY, UPPER(CASE WHEN LOWER(COALESCE(sc.FINAL_MARKETPLACE_PRE, msc.Marketplace, mscc.Marketplace)) LIKE \'%shopify%\' THEN \'WEBSITE\' ELSE COALESCE(sc.FINAL_MARKETPLACE_PRE, msc.Marketplace, mscc.Marketplace) END) AS FINAL_MARKETPLACE, UPPER(CASE WHEN UPPER(COALESCE(sc.marketplace_segment_pre, msc.marketplace_segment, mscc.marketplace_segment, msccc.marketplace_segment)) LIKE \'%OFFLINE%\' THEN \'OFFLINE\' ELSE \'ONLINE\' END) AS Business_Type, UPPER(COALESCE(sc.Brand_pre, msc.Brand, mscc.Brand, msccc.Brand)) AS Brand, sc.*, IFNULL(store_rent, 0) + IFNULL(store_cam, 0) + IFNULL(store_elec, 0) + IFNULL(store_int, 0) + IFNULL(store_hvac, 0) + IFNULL(store_other, 0) + IFNULL(store_salary, 0) + IFNULL(store_incentive, 0) + IFNULL(store_bank, 0) AS offline_store_cost, IFNULL(mscc.spend * SAFE_DIVIDE(GREATEST(IFNULL(sales, 0), 1), SUM(GREATEST(IFNULL(sales, 0), 1)) OVER (PARTITION BY COALESCE(sc.date_pre, msc.marketing_date, mscc.marketing_date, msccc.marketing_date), LOWER(COALESCE(sc.Channel_pre, msc.Channel, mscc.Channel, msccc.Channel)), LOWER(COALESCE(sc.Brand_pre, msc.Brand, mscc.Brand, msccc.Brand)), LOWER(COALESCE(mscc.collection, sc.collection_pre)))), 0) + IFNULL(msc.spend * SAFE_DIVIDE(GREATEST(IFNULL(sales, 0), 1), SUM(GREATEST(IFNULL(sales, 0), 1)) OVER (PARTITION BY COALESCE(sc.date_pre, msc.marketing_date, mscc.marketing_date, msccc.marketing_date), LOWER(COALESCE(sc.Channel_pre, msc.Channel, mscc.Channel, msccc.Channel)), LOWER(COALESCE(sc.Brand_pre, msc.Brand, mscc.Brand, msccc.Brand)), LOWER(COALESCE(msc.category, sc.category_pre)), LOWER(COALESCE(msc.collection, sc.collection_pre)))), 0) + IFNULL(msccc.spend * SAFE_DIVIDE(GREATEST(IFNULL(sales, 0), 1), SUM(GREATEST(IFNULL(sales, 0), 1)) OVER (PARTITION BY COALESCE(sc.date_pre, msc.marketing_date, mscc.marketing_date, msccc.marketing_date), LOWER(COALESCE(sc.channel_pre, msc.channel, mscc.channel, msccc.channel)), LOWER(COALESCE(sc.Brand_pre, msc.Brand, mscc.Brand, msccc.Brand)))), 0) AS Spend, IFNULL(mscc.Brand_Spend * SAFE_DIVIDE(GREATEST(IFNULL(sales, 0), 1), SUM(GREATEST(IFNULL(sales, 0), 1)) OVER (PARTITION BY COALESCE(sc.date_pre, msc.marketing_date, mscc.marketing_date, msccc.marketing_date), LOWER(COALESCE(sc.Channel_pre, msc.Channel, mscc.Channel, msccc.Channel)), LOWER(COALESCE(sc.Brand_pre, msc.Brand, mscc.Brand, msccc.Brand)), LOWER(COALESCE(mscc.collection, sc.collection_pre)))), 0) + IFNULL(msc.Brand_Spend * SAFE_DIVIDE(GREATEST(IFNULL(sales, 0), 1), SUM(GREATEST(IFNULL(sales, 0), 1)) OVER (PARTITION BY COALESCE(sc.date_pre, msc.marketing_date, mscc.marketing_date, msccc.marketing_date), LOWER(COALESCE(sc.Channel_pre, msc.Channel, mscc.Channel, msccc.Channel)), LOWER(COALESCE(sc.Brand_pre, msc.Brand, mscc.Brand, msccc.Brand)), LOWER(COALESCE(msc.category, sc.category_pre)), LOWER(COALESCE(msc.collection, sc.collection_pre)))), 0) + IFNULL(msccc.Brand_Spend * SAFE_DIVIDE(GREATEST(IFNULL(sales, 0), 1), SUM(GREATEST(IFNULL(sales, 0), 1)) OVER (PARTITION BY COALESCE(sc.date_pre, msc.marketing_date, mscc.marketing_date, msccc.marketing_date), LOWER(COALESCE(sc.Channel_pre, msc.Channel, mscc.Channel, msccc.Channel)), LOWER(COALESCE(sc.Brand_pre, msc.Brand, mscc.Brand, msccc.Brand)))), 0) AS Brand_Spend FROM cte sc FULL OUTER JOIN ( SELECT date AS marketing_date, MAX(CASE WHEN LOWER(channel) LIKE ANY (\'%facebook%\', \'%google%\') THEN \'SHOPIFY WEB\' WHEN LOWER(channel) LIKE ANY (\'%amazon%\') THEN \'AMAZON\' WHEN LOWER(channel) LIKE \'%flipkart%\' THEN \'FLIPKART\' WHEN LOWER(channel) LIKE \'%myntra%\' THEN \'MYNTRA\' ELSE UPPER(channel) END) AS Marketplace, CASE WHEN LOWER(channel) LIKE ANY (\'%facebook%\', \'%google%\') THEN \'D2C\' ELSE UPPER(channel) END AS Channel, MAX(CASE WHEN LOWER(channel) LIKE ANY (\'%facebook%\', \'%google%\') THEN \'D2C\' WHEN LOWER(channel) LIKE ANY (\'%amazon%\', \'%flipkart%\', \'%myntra%\', \'%nykaa%\') THEN \'E-COMMERCE\' ELSE \'E-COMMERCE\' END) AS Marketplace_segment, Brand, UPPER(category) AS category, MAX(collection) AS collection, SUM(IFNULL(spend, 0)) AS spend, SUM(CASE WHEN LOWER(REPLACE(IFNULL(campaign_name, \'\'), \'_\', \'$\')) LIKE ANY (\'%$top$%\', \'%instagram%\') THEN IFNULL(spend, 0) ELSE 0 END) AS Brand_Spend FROM `MapleMonk.STPL_MARKETING_CONSOLIDATED_temp` WHERE category IS NOT NULL AND NOT (LOWER(IFNULL(campaign_name, \'\')) LIKE \'%offline%\') GROUP BY 1, 3, 5, 6 ) msc ON CAST(msc.marketing_date AS DATE) = CAST(sc.date_pre AS DATE) AND LOWER(msc.Channel) = LOWER(sc.Channel_pre) AND LOWER(msc.Brand) = LOWER(sc.Brand_pre) AND LOWER(msc.category) = LOWER(sc.category_pre) FULL OUTER JOIN ( SELECT date AS marketing_date, MAX(CASE WHEN LOWER(channel) LIKE ANY (\'%facebook%\', \'%google%\') THEN \'SHOPIFY WEB\' WHEN LOWER(channel) LIKE ANY (\'%amazon%\') THEN \'AMAZON\' WHEN LOWER(channel) LIKE \'%flipkart%\' THEN \'FLIPKART\' WHEN LOWER(channel) LIKE \'%myntra%\' THEN \'MYNTRA\' ELSE UPPER(channel) END) AS Marketplace, CASE WHEN LOWER(channel) LIKE ANY (\'%facebook%\', \'%google%\') THEN \'D2C\' ELSE UPPER(channel) END AS Channel, MAX(CASE WHEN LOWER(channel) LIKE ANY (\'%facebook%\', \'%google%\') THEN \'D2C\' WHEN LOWER(channel) LIKE (\'%amazon%\') THEN \'E-COMMERCE\' ELSE \'QUICK-COMMERCE\' END) AS Marketplace_segment, Brand, UPPER(collection) AS collection, SUM(IFNULL(spend, 0)) AS spend, SUM(CASE WHEN LOWER(REPLACE(IFNULL(campaign_name, \'\'), \'_\', \'$\')) LIKE ANY (\'%$top$%\', \'%instagram%\') THEN IFNULL(spend, 0) ELSE 0 END) AS Brand_Spend FROM `MapleMonk.STPL_MARKETING_CONSOLIDATED_temp` WHERE category IS NULL AND collection IS NOT NULL AND NOT (LOWER(IFNULL(campaign_name, \'\')) LIKE \'%offline%\') GROUP BY 1, 3, 5, 6 ) mscc ON CAST(mscc.marketing_date AS DATE) = CAST(COALESCE(sc.date_pre, msc.marketing_date) AS DATE) AND LOWER(mscc.Channel) = LOWER(COALESCE(sc.Channel_pre, msc.Channel)) AND LOWER(mscc.Brand) = LOWER(COALESCE(sc.Brand_pre, msc.Brand)) AND LOWER(mscc.collection) = LOWER(sc.collection_pre) FULL OUTER JOIN ( SELECT date AS marketing_date, MAX(CASE WHEN LOWER(channel) LIKE ANY (\'%facebook%\', \'%google%\') THEN \'SHOPIFY WEB\' WHEN LOWER(channel) LIKE ANY (\'%amazon%\') THEN \'AMAZON\' WHEN LOWER(channel) LIKE \'%flipkart%\' THEN \'FLIPKART\' WHEN LOWER(channel) LIKE \'%myntra%\' THEN \'MYNTRA\' ELSE UPPER(channel) END) AS Marketplace, CASE WHEN LOWER(channel) LIKE ANY (\'%facebook%\', \'%google%\') THEN \'D2C\' ELSE UPPER(channel) END AS Channel, MAX(CASE WHEN LOWER(channel) LIKE ANY (\'%facebook%\', \'%google%\') THEN \'D2C\' WHEN LOWER(channel) LIKE ANY (\'%flipkart%\', \'%amazon%\', \'%myntra%\', \'%nykaa%\') THEN \'E-COMMERCE\' ELSE \'QUICK-COMMERCE\' END) AS Marketplace_segment, Brand, SUM(IFNULL(spend, 0)) AS spend, SUM(CASE WHEN LOWER(REPLACE(IFNULL(campaign_name, \'\'), \'_\', \'$\')) LIKE ANY (\'%$top$%\', \'%instagram%\') THEN IFNULL(spend, 0) ELSE 0 END) AS Brand_Spend FROM `MapleMonk.STPL_MARKETING_CONSOLIDATED_temp` WHERE category IS NULL AND collection IS NULL AND NOT (LOWER(IFNULL(campaign_name, \'\')) LIKE \'%offline%\') GROUP BY 1, 3, 5 ) msccc ON CAST(msccc.marketing_date AS DATE) = CAST(COALESCE(sc.date_pre, msc.marketing_date, mscc.marketing_date) AS DATE) AND LOWER(msccc.Channel) = LOWER(COALESCE(sc.Channel_pre, msc.Channel, mscc.Channel)) AND LOWER(msccc.Brand) = LOWER(COALESCE(sc.Brand_pre, msc.Brand, mscc.Brand));",
                    "transaction": true
                }
            ) }}
            with sample_data as (

